// Normalize Analytics Data
//
// Input : one item = the raw Athena GetQueryResults response.
// Output: one item = analytics rows grouped by level, in Athena's own order.
//
// This node does NOT calculate anything. Athena is the source of truth for
// period generation, aggregation, metric calculation and ordering.

const SUPPORTED_LEVELS = ['year', 'month', 'week', 'day', '3h'];

const NUMERIC_COLUMNS = [
  'ftd',
  'total_dep',
  'in_out',
  'hold',
  'reg2dep',
  'ftd2std',
  'ar_psp',
  'ar_psp_deposits',
];

/** Athena returns every value as a string, or omits VarCharValue entirely for NULL. */
function cellValue(cell) {
  if (cell === null || cell === undefined) return null;
  const raw = cell.VarCharValue;
  if (raw === null || raw === undefined) return null;
  return String(raw);
}

/** Numbers arrive as strings. Anything unparseable becomes null, never NaN. */
function toNumber(raw) {
  if (raw === null || raw === undefined) return null;
  const trimmed = String(raw).trim();
  if (trimmed === '') return null;
  const parsed = Number(trimmed);
  return Number.isFinite(parsed) ? parsed : null;
}

const inputItems = $input.all();
if (inputItems.length !== 1) {
  throw new Error(
    `Normalize Analytics Data expected exactly 1 input item from Athena, received ${inputItems.length}.`,
  );
}

const response = inputItems[0].json ?? {};

if (response.NextToken) {
  throw new Error(
    'Athena returned a paginated result (NextToken present). This workflow reads a single ' +
      'page of up to 1000 rows and does not implement pagination. The analytics query is not ' +
      'expected to exceed that; if it now does, add pagination before trusting this report.',
  );
}

const resultSet = response.ResultSet;
if (!resultSet || !Array.isArray(resultSet.Rows)) {
  throw new Error(
    'Unexpected Athena response: ResultSet.Rows is missing. Check the Get Athena Results node output.',
  );
}

const columns = (resultSet.ResultSetMetadata?.ColumnInfo ?? []).map((column) => column?.Name);
if (columns.length === 0) {
  throw new Error('Unexpected Athena response: ResultSetMetadata.ColumnInfo is empty.');
}

// Athena prepends a header row whose values are the column names. It is metadata, not data.
let rows = resultSet.Rows;
const firstRowValues = (rows[0]?.Data ?? []).map(cellValue);
const firstRowIsHeader =
  firstRowValues.length === columns.length &&
  firstRowValues.every((value, index) => value === columns[index]);
if (firstRowIsHeader) {
  rows = rows.slice(1);
}

const grouped = { year: [], month: [], week: [], day: [], '3h': [] };
const unknownLevels = new Set();
let rowCount = 0;

for (const row of rows) {
  const cells = row?.Data ?? [];

  const record = {};
  columns.forEach((columnName, index) => {
    record[columnName] = cellValue(cells[index]);
  });

  // Skip rows that carry no values at all rather than emitting a row of dashes.
  if (Object.values(record).every((value) => value === null)) continue;

  const level = record.level === null ? null : record.level.trim();
  if (!level || !SUPPORTED_LEVELS.includes(level)) {
    unknownLevels.add(String(record.level));
    continue;
  }

  const normalized = {
    level,
    period: record.period === null ? null : record.period.trim(),
  };
  for (const column of NUMERIC_COLUMNS) {
    normalized[column] = toNumber(record[column]);
  }

  grouped[level].push(normalized);
  rowCount += 1;
}

if (unknownLevels.size > 0) {
  throw new Error(
    `Athena returned unsupported level value(s): ${[...unknownLevels].join(', ')}. ` +
      `Supported levels are ${SUPPORTED_LEVELS.join(', ')}. ` +
      'The analytics SQL and this node have drifted apart — update both together.',
  );
}

if (rowCount === 0) {
  throw new Error(
    'Athena query succeeded but returned zero analytics rows. No Slack report was sent. ' +
      'Check that the source tables have data for the current periods.',
  );
}

return [{ json: grouped }];

// Build Slack Payload
//
// Input : one item = analytics rows grouped by level (from Normalize Analytics Data).
// Output: exactly one item = the complete Slack Incoming Webhook payload.
//
// This node only presents data: Block Kit structure, labels, number formatting and the
// Europe/Kyiv report timestamp. It never recalculates a metric.

const REPORT_TIMEZONE = 'Europe/Kyiv';
const MISSING = '—';
const SLACK_MAX_BLOCKS = 50;

// Rendering order inside every period. Two columns per row in Slack's section.fields.
const METRIC_FIELDS = [
  { key: 'ftd', label: 'FTD', format: 'integer' },
  { key: 'total_dep', label: 'Total Dep', format: 'integer' },
  { key: 'in_out', label: 'In-Out', format: 'integer' },
  { key: 'hold', label: 'Hold', format: 'percent' },
  { key: 'reg2dep', label: 'Reg2Dep', format: 'percent' },
  { key: 'ftd2std', label: 'Ftd2Std', format: 'percent' },
  { key: 'ar_psp', label: 'AR PSP', format: 'percent' },
  { key: 'ar_psp_deposits', label: 'AR PSP Deposits', format: 'percent' },
];

function toFiniteNumber(value) {
  if (value === null || value === undefined) return null;
  const parsed = typeof value === 'number' ? value : Number(String(value).trim());
  return Number.isFinite(parsed) ? parsed : null;
}

function formatInteger(value) {
  const parsed = toFiniteNumber(value);
  if (parsed === null) return MISSING;
  return Math.round(parsed).toLocaleString('en-US');
}

function formatPercent(value) {
  const parsed = toFiniteNumber(value);
  if (parsed === null) return MISSING;
  return `${parsed.toFixed(1)}%`;
}

function formatMetric(row, field) {
  return field.format === 'integer' ? formatInteger(row[field.key]) : formatPercent(row[field.key]);
}

/** Slack mrkdwn reserves these three characters. */
function escapeMrkdwn(text) {
  return String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function formatInTimezone(date, options) {
  return new Intl.DateTimeFormat(options.locale ?? 'en-GB', {
    timeZone: REPORT_TIMEZONE,
    ...options.parts,
  }).format(date);
}

const inputItems = $input.all();
if (inputItems.length !== 1) {
  throw new Error(
    `Build Slack Payload expected exactly 1 input item, received ${inputItems.length}.`,
  );
}

const grouped = inputItems[0].json ?? {};

const now = new Date();
const reportDate = formatInTimezone(now, {
  parts: { day: '2-digit', month: 'short', year: 'numeric' },
});
const reportTime = formatInTimezone(now, {
  parts: { hour: '2-digit', minute: '2-digit', hour12: false },
});
const currentMonthName = formatInTimezone(now, {
  locale: 'en-US',
  parts: { month: 'long' },
}).toUpperCase();

const GROUPS = [
  { key: 'year', heading: 'YEAR' },
  { key: 'month', heading: 'MONTHS' },
  { key: 'week', heading: `WEEKS — ${currentMonthName}` },
  { key: 'day', heading: 'DAYS — CURRENT WEEK' },
  { key: '3h', heading: '3H — LATEST DAY' },
];

function periodBlock(row) {
  const period =
    typeof row.period === 'string' && row.period.trim() !== '' ? row.period.trim() : MISSING;

  return {
    type: 'section',
    text: { type: 'mrkdwn', text: `*${escapeMrkdwn(period)}*` },
    fields: METRIC_FIELDS.map((field) => ({
      type: 'mrkdwn',
      text: `*${field.label}*\n${formatMetric(row, field)}`,
    })),
  };
}

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: '📊 Analytics Report', emoji: true } },
  {
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text: `${reportDate} • ${REPORT_TIMEZONE} • Updated ${reportTime}`,
      },
    ],
  },
];

for (const group of GROUPS) {
  const rows = Array.isArray(grouped[group.key]) ? grouped[group.key] : [];
  // A level with no rows is skipped rather than rendered as an empty heading.
  if (rows.length === 0) continue;

  blocks.push({ type: 'divider' });
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*${group.heading}*` } });
  for (const row of rows) {
    blocks.push(periodBlock(row));
  }
}

// Only the header and context blocks means every level came back empty.
if (blocks.length <= 2) {
  throw new Error(
    'No analytics periods to report — every level was empty after normalization. ' +
      'No Slack report was sent.',
  );
}

if (blocks.length > SLACK_MAX_BLOCKS) {
  throw new Error(
    `Slack payload has ${blocks.length} blocks, above Slack's limit of ${SLACK_MAX_BLOCKS}. ` +
      'Athena returned more periods than this report layout allows.',
  );
}

return [
  {
    json: {
      text: `Analytics Report — ${reportDate}`,
      blocks,
    },
  },
];
